import { expect, expectStatus, test, type APIRequestContext } from "../fixtures";

type Doc = { id: string; kind: string; status: string };
type Extraction = { id: string; kind: string; status: string };
type Vendor = { id: string; status: string };
type QueueItem = { vendor_id: string; extractions: Extraction[] };

const uniqueName = (label: string) =>
  `${label} ${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

async function uploadDocument(
  member: APIRequestContext,
  vendorId: string,
  kind: "w9" | "insurance_certificate" | "contract",
): Promise<Doc> {
  const response = await member.post(`/api/vendors/${vendorId}/documents`, {
    multipart: {
      kind,
      file: {
        name: `${kind}-${Date.now()}.pdf`,
        mimeType: "application/pdf",
        buffer: Buffer.from(`%PDF-1.4 ${kind} ${Math.random()}`),
      },
    },
  });
  return expectStatus<Doc>(response, 201);
}

async function waitForExtracted(member: APIRequestContext, documentId: string): Promise<void> {
  await expect
    .poll(
      async () => {
        const doc = await expectStatus<Doc>(await member.get(`/api/documents/${documentId}`), 200);
        return doc.status;
      },
      { timeout: 60_000, intervals: [500, 1000, 2000] },
    )
    .toBe("extracted");
}

async function extractionFor(member: APIRequestContext, documentId: string): Promise<Extraction> {
  return expectStatus<Extraction>(await member.get(`/api/documents/${documentId}/extraction`), 200);
}

async function decide(
  reviewer: APIRequestContext,
  extractionId: string,
  decision: "approve" | "reject",
): Promise<Extraction> {
  return expectStatus<Extraction>(
    await reviewer.post(`/api/extractions/${extractionId}/decision`, {
      data: { decision, note: `${decision} for lifecycle test` },
    }),
    200,
  );
}

test(
  "after a replacement, only the new document waits for review",
  { tag: "@LIF-05" },
  async ({ apiAs }) => {
    // Arrange: member creates a vendor and uploads the three required documents.
    const member = await apiAs("member");
    const reviewer = await apiAs("reviewer");

    const vendor = await expectStatus<Vendor>(
      await member.post("/api/vendors", {
        data: {
          name: uniqueName("Lifecycle Vendor"),
          category: "services",
          contact_email: `lifecycle-${Date.now()}@example.test`,
        },
      }),
      201,
    );

    const insurance = await uploadDocument(member, vendor.id, "insurance_certificate");
    const contract = await uploadDocument(member, vendor.id, "contract");
    const w9 = await uploadDocument(member, vendor.id, "w9");

    await waitForExtracted(member, insurance.id);
    await waitForExtracted(member, contract.id);
    await waitForExtracted(member, w9.id);

    const insuranceExtraction = await extractionFor(member, insurance.id);
    const contractExtraction = await extractionFor(member, contract.id);
    const w9Extraction = await extractionFor(member, w9.id);

    // Reviewer approves insurance and contract, rejects the w9.
    await decide(reviewer, insuranceExtraction.id, "approve");
    await decide(reviewer, contractExtraction.id, "approve");
    const rejected = await decide(reviewer, w9Extraction.id, "reject");
    expect(rejected.status).toBe("rejected");

    // Act: member replaces the w9, waits for extraction, and submits again.
    const newW9 = await uploadDocument(member, vendor.id, "w9");
    await waitForExtracted(member, newW9.id);
    const newW9Extraction = await extractionFor(member, newW9.id);

    const resubmitted = await expectStatus<Vendor>(
      await member.post(`/api/vendors/${vendor.id}/submit`),
      200,
    );

    // Assert: vendor is back in review.
    expect(resubmitted.status).toBe("in_review");

    // Assert: the review queue lists the vendor with exactly one pending extraction, a w9.
    const queue = await expectStatus<QueueItem[]>(await reviewer.get("/api/review-queue"), 200);
    const item = queue.find((entry) => entry.vendor_id === vendor.id);
    expect(item, "vendor should appear in the review queue").toBeDefined();

    const pending = item!.extractions.filter((e) => e.status === "pending_review");
    expect(pending).toHaveLength(1);
    expect(pending[0].kind).toBe("w9");
    expect(pending[0].id).toBe(newW9Extraction.id);
  },
);
